// Tile painting runs off the input/animation thread. Only the latest view is queued.
import {makeMaterials} from './map-style.js';
import {Cartography} from './cartography.js';
import {SpatialIndex} from './geography.js';
let painter,queue=[],busy=false;
async function drain(){if(busy||!painter)return;busy=true;while(queue.length){const {x,y,layout,key,generation}=queue.shift();try{const canvas=painter.tile(x,y,layout),bitmap=canvas.transferToImageBitmap();painter.tiles.clear();postMessage({type:'tile',key,bitmap,generation},[bitmap]);}catch(error){postMessage({type:'error',message:String(error)});}await new Promise(resolve=>setTimeout(resolve,0));}busy=false;}
self.onmessage=async({data:m})=>{if(m.type==='init'){try{const w=m.world;w.project=p=>[(p[0]-w.origin[0])*w.mLon,(w.origin[1]-p[1])*111320];w.features.forEach((f,i)=>f.renderOrder=i);painter=Object.assign(Object.create(Cartography.prototype),{w,index:new SpatialIndex(w.features),tiles:new Map(),surface:(w,h)=>new OffscreenCanvas(w,h),terrain:{naturalWidth:0}});const[terrain,materials]=await Promise.all([fetch(m.terrain).then(r=>{if(!r.ok)throw Error('terrain');return r.blob();}).then(createImageBitmap),fetch(m.materials).then(r=>{if(!r.ok)throw Error('materials');return r.blob();}).then(createImageBitmap).catch(()=>null),typeof FontFace!=='undefined'?new FontFace('NanumRound',`url(${m.font})`,{weight:'100 900'}).load().then(f=>self.fonts.add(f)).catch(()=>{}):null]);if(materials){painter.materials=makeMaterials(materials,(w,h)=>new OffscreenCanvas(w,h));materials.close();}painter.terrain=terrain;painter.terrainWidth=terrain.width;painter.terrainHeight=terrain.height;postMessage({type:'ready'});drain();}catch(error){postMessage({type:'error',message:String(error)});}}else if(m.type==='view'){queue=m.tiles;drain();}};
